head.script:
scwin.screenId = "jldfil35704";

///////// 1. 변수 및 선언 영역 /////////

scwin.subTitle1 = $c.util.getComponent('subTitle1');

scwin.data = null;

scwin.calType = '';


///////// 2. 초기화 영역 /////////

/**
 * @method
 * @name onpageload
 * @description 화면 진입점 — 초기화 함수(init_*)를 데이터 의존성 순서로 순차 실행한다.
 * @returns {void}
 * @hidden N
 * @example (body ev:onpageload 바인딩으로 자동 호출)
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam(); // 1) 파라미터 수신
        await scwin.init_pageBody(); // 2) 수수료 계산 결과 렌더 + 인쇄 호출
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldfil35704.onpageload' });
    }
};

/**
 * @method
 * @name init_pageBody
 * @description 페이지 본문 초기화 — fn_init 를 호출해 호스트 화면에서 받은 상장수수료 계산 데이터를 렌더하고, 실패 시 공통 오류 처리한다.
 * @returns {void}
 * @hidden N
 * @example await scwin.init_pageBody();
 */
scwin.init_pageBody = async function () {
    try {
        await scwin.fn_init();
    } catch (ex) {
        await $c.exception.handleError(ex, { context: 'jldfil35704.onpageload' });
    }
};

// 화면 전환 파라미터 수신 — 공용 $c.data.recvParamData (§106, 이름 고정 "paramData"; 실패 표출은 gcc 함수 몫). onpageload 합성 단계.
/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터를 dma_pageContext 로 수신한다(공용 $c.data.recvParamData, 이름 고정 "paramData").
 * @returns {void}
 * @hidden N
 * @example scwin.init_recvParam();
 */
scwin.init_recvParam = function () {
    $c.data.recvParamData('dma_pageContext');
};


///////// 3. 컴포넌트 이벤트 영역 /////////



///////// 4. 서브미션 콜백 영역 /////////



///////// 5. 일반/업무 함수 영역 /////////

/**
 * @method
 * @name fn_init
 * @description 호스트 화면(파라미터 dataArr 또는 오프너 scwin.dataArr)에서 상장수수료 계산 데이터를 받아 시장구분·수수료구분·상장방식을 판정해 표기하고, 종목별 상장주식수/종가/상장금액과 합계·최저한도·부과수수료를 입력 필드에 렌더한 뒤 인쇄 팝업($c.win.popupPrint)을 호출한다.
 * @returns {void}
 * @hidden N
 * @example await scwin.fn_init();
 */
scwin.fn_init = async function () {
    const param = $c.data.getParameter();
    const openerScwin = ((($c.win && $c.win.getOpenerScope) ? $c.win.getOpenerScope() : null) || {}).scwin || {};
    const dataSrc = (param && typeof param === 'object' && Object.keys(param).length) ? param : openerScwin;
    scwin.data = dataSrc.dataArr;
    if (!Array.isArray(scwin.data)) {
        console.warn('[sdd] 인쇄 데이터 부재(호스트 진입 필요) — jldfil35704');
        return;
    }
    let strCalc = "";
    let strListTp = "";
    if (scwin.data[0] == null && scwin.data[1] == null && scwin.data[2] == null && scwin.data[3] == null && scwin.data[4] == null &&
        scwin.data[5] == null && scwin.data[6] == null && scwin.data[7] == null && scwin.data[8] == null && scwin.data[9] == null) {
        if (scwin.data[10].mkt_gubun === "1") {
            switch (scwin.data[10].listTp_gubun) {
                case '1':
                strListTp = "신규상장";
                break;
                case '2':
                strListTp = "추가/재상장";
                break;
                case '3':
                strListTp = "변경상장";
                break;
            }
            switch (scwin.data[10].calc_gubun) {
                case '1':
                strCalc = "보통주권/외국주권/종류주권/기업인수목적회사주권";
                break;
                case '2':
                strCalc = "집합투자증권";
                break;
                case '3':
                strCalc = "수익증권";
                break;
                case '4':
                strCalc = "신주인수권증권 ";
                break;
            }
            scwin.subTitle1.setStyle("display", 'block');
            $c.util.getComponent("ipt_mktGubun").setValue("유가증권시장");
            $c.util.getComponent("ipt_calcGubun").setValue(strCalc);
            $c.util.getComponent("ipt_listTpGubun").setValue(strListTp);
        } else {
            if (scwin.data[10].mkt_gubun === "2") {
                $c.util.getComponent("ipt_mktGubun").setValue("코스닥시장");
                if (scwin.data[10].calc_gubun === "1") {
                    $c.util.getComponent("ipt_calcGubun").setValue("주권/외국주권/외국주식예탁증권(DR)");
                } else {
                    if (scwin.data[10].calc_gubun === "6") {
                        $c.util.getComponent("ipt_calcGubun").setValue("신주인수권증권");
                    }
                }
                scwin.subTitle1.setStyle("display", '');
                if (scwin.data[10].listTp_gubun === "1") {
                    $c.util.getComponent("ipt_listTpGubun").setValue("신규상장");
                } else {
                    if (scwin.data[10].listTp_gubun === "2") {
                        $c.util.getComponent("ipt_listTpGubun").setValue("추가/재상장");
                    }
                }
            } else {
                if (scwin.data[10].mkt_gubun === "6") {
                    $c.util.getComponent("ipt_mktGubun").setValue("코넥스시장");
                    $c.util.getComponent("ipt_calcGubun").setValue("주권");
                    scwin.subTitle1.setStyle("display", '');
                    $c.util.getComponent("ipt_listTpGubun").setValue("신규/변경(자본금증가)/재/추가상장");
                } else {
                    if (scwin.data[10].mkt_gubun === "D") {
                        $c.util.getComponent("ipt_mktGubun").setValue("신종증권");
                        switch (scwin.data[10].calc_gubun) {
                            case '1':
                            strCalc = "신탁수익증권";
                            break;
                            case '2':
                            strCalc = "투자계약증권";
                            break;
                        }
                        $c.util.getComponent("ipt_calcGubun").setValue(strCalc);
                        scwin.subTitle1.setStyle("display", 'none');
                        $c.util.getComponent("ipt_listTpGubun").setValue("");
                    }
                }
            }
        }
        $c.util.getComponent("ipt_totListAmt").setValue(scwin.data[11].tot_list_amt);
        $c.util.getComponent("ipt_listCommSum").setValue(scwin.data[11].list_comm_sum);
        $c.util.getComponent("ipt_listCommSumMin").setValue(scwin.data[11].list_comm_sum_min);
        $c.util.getComponent("ipt_listCommSumAdd").setValue(scwin.data[11].list_comm_sum_add);
    }
    $c.util.getComponent("ipt_stockCount1").setValue(scwin.data[0].stock_count);
    $c.util.getComponent("ipt_stockCount2").setValue(scwin.data[1].stock_count);
    $c.util.getComponent("ipt_stockCount3").setValue(scwin.data[2].stock_count);
    $c.util.getComponent("ipt_stockCount4").setValue(scwin.data[3].stock_count);
    $c.util.getComponent("ipt_stockCount5").setValue(scwin.data[4].stock_count);
    $c.util.getComponent("ipt_stockCount6").setValue(scwin.data[5].stock_count);
    $c.util.getComponent("ipt_stockCount7").setValue(scwin.data[6].stock_count);
    $c.util.getComponent("ipt_stockCount8").setValue(scwin.data[7].stock_count);
    $c.util.getComponent("ipt_stockCount9").setValue(scwin.data[8].stock_count);
    $c.util.getComponent("ipt_stockCount10").setValue(scwin.data[9].stock_count);
    $c.util.getComponent("ipt_parval1").setValue(scwin.data[0].parval);
    $c.util.getComponent("ipt_parval2").setValue(scwin.data[1].parval);
    $c.util.getComponent("ipt_parval3").setValue(scwin.data[2].parval);
    $c.util.getComponent("ipt_parval4").setValue(scwin.data[3].parval);
    $c.util.getComponent("ipt_parval5").setValue(scwin.data[4].parval);
    $c.util.getComponent("ipt_parval6").setValue(scwin.data[5].parval);
    $c.util.getComponent("ipt_parval7").setValue(scwin.data[6].parval);
    $c.util.getComponent("ipt_parval8").setValue(scwin.data[7].parval);
    $c.util.getComponent("ipt_parval9").setValue(scwin.data[8].parval);
    $c.util.getComponent("ipt_parval10").setValue(scwin.data[9].parval);
    $c.util.getComponent("ipt_listAmt1").setValue(scwin.data[0].list_amt);
    await scwin.numFormat($c.util.fieldEl('ipt_listAmt1', 'list_amt1'));
    $c.util.getComponent("ipt_listAmt2").setValue(scwin.data[1].list_amt);
    await scwin.numFormat($c.util.fieldEl('ipt_listAmt2', 'list_amt2'));
    $c.util.getComponent("ipt_listAmt3").setValue(scwin.data[2].list_amt);
    await scwin.numFormat($c.util.fieldEl('ipt_listAmt3', 'list_amt3'));
    $c.util.getComponent("ipt_listAmt4").setValue(scwin.data[3].list_amt);
    await scwin.numFormat($c.util.fieldEl('ipt_listAmt4', 'list_amt4'));
    $c.util.getComponent("ipt_listAmt5").setValue(scwin.data[4].list_amt);
    await scwin.numFormat($c.util.fieldEl('ipt_listAmt5', 'list_amt5'));
    $c.util.getComponent("ipt_listAmt6").setValue(scwin.data[5].list_amt);
    await scwin.numFormat($c.util.fieldEl('ipt_listAmt6', 'list_amt6'));
    $c.util.getComponent("ipt_listAmt7").setValue(scwin.data[6].list_amt);
    await scwin.numFormat($c.util.fieldEl('ipt_listAmt7', 'list_amt7'));
    $c.util.getComponent("ipt_listAmt8").setValue(scwin.data[7].list_amt);
    await scwin.numFormat($c.util.fieldEl('ipt_listAmt8', 'list_amt8'));
    $c.util.getComponent("ipt_listAmt9").setValue(scwin.data[8].list_amt);
    await scwin.numFormat($c.util.fieldEl('ipt_listAmt9', 'list_amt9'));
    $c.util.getComponent("ipt_listAmt10").setValue(scwin.data[9].list_amt);
    await scwin.numFormat($c.util.fieldEl('ipt_listAmt10', 'list_amt10'));
    if (scwin.data[10].mkt_gubun === "1") {
        switch (scwin.data[10].listTp_gubun) {
            case '1':
            strListTp = "신규상장";
            break;
            case '2':
            strListTp = "추가/재상장";
            break;
            case '3':
            strListTp = "변경상장";
            break;
        }
        switch (scwin.data[10].calc_gubun) {
            case "1":
            strCalc = "보통주권/외국주권/종류주권/기업인수목적회사주권";
            break;
            case "2":
            strCalc = "집합투자증권";
            break;
            case "3":
            strCalc = "수익증권";
            break;
            case "4":
            strCalc = "신주인수권증권 ";
            break;
        }
        scwin.subTitle1.setStyle("display", 'block');
        $c.util.getComponent("ipt_mktGubun").setValue("유가증권시장");
        $c.util.getComponent("ipt_calcGubun").setValue(strCalc);
        $c.util.getComponent("ipt_listTpGubun").setValue(strListTp);
    } else {
        if (scwin.data[10].mkt_gubun === "2") {
            $c.util.getComponent("ipt_mktGubun").setValue("코스닥시장");
            if (scwin.data[10].calc_gubun === "1") {
                $c.util.getComponent("ipt_calcGubun").setValue("주권/외국주권/외국주식예탁증권(DR)");
            } else {
                if (scwin.data[10].calc_gubun === "6") {
                    $c.util.getComponent("ipt_calcGubun").setValue("신주인수권증권");
                }
            }
            scwin.subTitle1.setStyle("display", '');
            if (scwin.data[10].listTp_gubun === "1") {
                $c.util.getComponent("ipt_listTpGubun").setValue("신규상장");
            } else {
                if (scwin.data[10].listTp_gubun === "2") {
                    $c.util.getComponent("ipt_listTpGubun").setValue("추가/재상장");
                }
            }
        } else {
            if (scwin.data[10].mkt_gubun === "6") {
                $c.util.getComponent("ipt_mktGubun").setValue("코넥스시장");
                $c.util.getComponent("ipt_calcGubun").setValue("주권");
                scwin.subTitle1.setStyle("display", '');
                $c.util.getComponent("ipt_listTpGubun").setValue("신규/변경(자본금증가)/재/추가상장");
            } else {
                if (scwin.data[10].mkt_gubun === "D") {
                    $c.util.getComponent("ipt_mktGubun").setValue("신종증권");
                    switch (scwin.data[10].calc_gubun) {
                        case '1':
                        strCalc = "신탁수익증권";
                        break;
                        case '2':
                        strCalc = "투자계약증권";
                        break;
                    }
                    $c.util.getComponent("ipt_calcGubun").setValue(strCalc);
                    scwin.subTitle1.setStyle("display", 'none');
                    $c.util.getComponent("ipt_listTpGubun").setValue("");
                }
            }
        }
    }
    $c.util.getComponent("ipt_totListAmt").setValue(scwin.data[11].tot_list_amt);
    $c.util.getComponent("ipt_listCommSum").setValue(scwin.data[11].list_comm_sum);
    $c.util.getComponent("ipt_listCommSumMin").setValue(scwin.data[11].list_comm_sum_min);
    $c.util.getComponent("ipt_listCommSumAdd").setValue(scwin.data[11].list_comm_sum_add);
    $c.win.popupPrint();
};


/**
 * @method
 * @name unformat
 * @description 입력 요소 값에서 숫자(0~9)와 부호(-)만 남기고 콤마 등 나머지 문자를 제거해 되돌려 넣는다.
 * @param {Object} obj value 속성을 가진 입력 요소
 * @returns {Boolean} 항상 true
 * @hidden N
 * @example scwin.unformat(obj);
 */
scwin.unformat = function (obj) {
    let temp = "";
    const n = String(obj.value);
    const len = n.length;
    let pos = 0;
    let ch = '';
    while (pos < len) {
        ch = n.charAt(pos);
        if (((ch >= '0') && (ch <= '9')) || (ch === '-')) {
            temp = temp + ch;
        }
        pos = pos + 1;
    }
    obj.value = temp;
    return true;
};


/**
 * @method
 * @name numFormat
 * @description 입력 요소 값을 숫자 검증(isMinusNum) 후 3자리 콤마 형식으로 변환한다. 숫자가 아니면 값을 비우고 경고 알림 후 포커스를 되돌린다.
 * @param {Object} obj value 속성을 가진 입력 요소
 * @returns {void}
 * @hidden N
 * @example await scwin.numFormat(obj);
 */
scwin.numFormat = async function (obj) {
    if (obj.value !== "" && !scwin.isMinusNum(obj.value)) {
        obj.value = "";
        await $c.win.alert("숫자만 입력가능합니다.");
        obj.focus();
        return;
    }
    scwin.unformat(obj);
    if (obj.value === "") {
        return;
    }
    if (isNaN(obj.value)) {
        obj.value = "";
        return;
    }
    let str = Number(obj.value) + "";
    let sMinusChar = "";
    if (Number(obj.value) < 0) {
        str = str.substring(1);
        sMinusChar = "-";
    }
    const leng = str.length;
    const size = 3;
    const cnt = Math.floor(leng / size);
    const pos = leng % size;
    let result = "";
    if (cnt === 0) {
        obj.value = Number(obj.value);
        return;
    }
    for (let i = cnt; i > 0; i = i - 1) {
        result = "," + str.substr(pos + (i - 1) * size, size) + result;
    }
    if (result !== '') {
        if (pos === 0) {
            obj.value = sMinusChar + result.substring(1);
        } else {
            obj.value = sMinusChar + str.substr(0, pos) + result;
        }
    }
    return;
};


/**
 * @method
 * @name isMinusNum
 * @description 문자열이 부호(-) 허용 숫자인지 판별한다 — 첫 글자는 0~9 또는 '-', 이후 글자는 모두 0~9 여야 true.
 * @param {String} name 검사할 문자열
 * @returns {Boolean} 부호 허용 숫자 여부
 * @hidden N
 * @example const ok = scwin.isMinusNum("-1234");
 */
scwin.isMinusNum = function (name) {
    let ch = "\0";
    let flag = true;
    ch = name.charAt(0);
    flag = ((ch >= '0' && ch <= '9') || ch === '-') ? true : false;
    for (let i = 1; (i < name.length) && (flag); i = i + 1) {
        ch = name.charAt(i);
        if ((ch >= '0') && (ch <= '9')) {

        } else {
            flag = false;
        }
    }
    return flag;
};
